import * as THREE from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
import {demoModel,validateModel,distance,csv} from './core.mjs';
const $=id=>document.getElementById(id),status=(text,error=false)=>{$('status').textContent=text;$('status').classList.toggle('error',error);};
let model=null,object=null,pair=[],measuring=false,busy=false,down=null,span=5,db=null;
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(45,1,.01,10000000),marks=new THREE.Group();
scene.add(marks);scene.add(new THREE.HemisphereLight(0xd7eeff,0x344156,3));
const light=new THREE.DirectionalLight(0xffffff,2);light.position.set(4,9,7);scene.add(light);
let renderer,controls;
try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));$('viewport').append(renderer.domElement);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;camera.position.set(7,6,8);controls.update();
new ResizeObserver(()=>{const r=$('viewport').getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}).observe($('viewport'));
renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera);});
renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();status('หน่วยความจำกราฟิกไม่พอ กรุณาดาวน์โหลดสำรองและโหลดหน้าใหม่',true);});
}catch(error){status('เบราว์เซอร์นี้เปิด WebGL ไม่สำเร็จ กรุณาใช้เบราว์เซอร์ที่รองรับ',true);$('demo').disabled=true;$('file').disabled=true;}
const dispose=node=>{node.traverse(n=>{n.geometry?.dispose();if(n.material)(Array.isArray(n.material)?n.material:[n.material]).forEach(m=>m.dispose());});};
function buttons(){for(const id of ['fit','measure','clear','saveProject','download'])$(id).disabled=!model||busy;$('csv').disabled=!model?.measurements.length||busy;$('saveMeasurement').disabled=pair.length!==2||busy;$('file').disabled=busy||!renderer;$('demo').disabled=busy||!renderer;$('measure').setAttribute('aria-pressed',String(measuring));}
function drawPair(){for(const child of [...marks.children]){dispose(child);marks.remove(child);}for(let i=0;i<pair.length;i++){const dot=new THREE.Mesh(new THREE.SphereGeometry(Math.max(span*.007,.006),16,12),new THREE.MeshBasicMaterial({color:i?0x86efa7:0x56d9f1,depthTest:false}));dot.position.fromArray(pair[i]);dot.renderOrder=10;marks.add(dot);}if(pair.length===2){const g=new THREE.BufferGeometry().setFromPoints(pair.map(p=>new THREE.Vector3(...p)));const line=new THREE.Line(g,new THREE.LineBasicMaterial({color:0x86efa7,depthTest:false}));line.renderOrder=10;marks.add(line);$('distance').textContent=distance(...pair).toFixed(3)+' m';$('hint').textContent='ระยะเส้นตรง A → B · ใส่ชื่อเพื่อบันทึก';}else{$('distance').textContent='— m';$('hint').textContent=pair.length?'เลือกจุด B บนโมเดล':'เปิดโหมดวัด แล้วแตะพื้นผิวสองจุด';}buttons();}
function fit(){if(!object)return;const box=new THREE.Box3().setFromObject(object),center=box.getCenter(new THREE.Vector3());span=Math.max(box.getSize(new THREE.Vector3()).length(),.1);camera.near=Math.max(span/10000,.001);camera.far=Math.max(span*100,100);camera.position.copy(center).add(new THREE.Vector3(.8,.65,1).multiplyScalar(span));camera.updateProjectionMatrix();controls.target.copy(center);controls.minDistance=span*.01;controls.maxDistance=span*20;controls.update();}
function show(next){validateModel(next);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(next.positions,3));let n;if(next.indices.length){g.setIndex(next.indices);g.computeVertexNormals();n=new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:0xf2a75c,roughness:.85,metalness:.05,side:THREE.DoubleSide}));}else{n=new THREE.Points(g,new THREE.PointsMaterial({color:0x79d7e5,size:.025,sizeAttenuation:true}));}if(object){scene.remove(object);dispose(object);}object=n;scene.add(object);model=next;model.id??=crypto.randomUUID();pair=[];measuring=false;$('empty').hidden=true;$('empty').style.display='none';$('modelName').textContent=model.name;$('source').textContent=model.synthetic?'ข้อมูลจำลอง / DEMO':String(model.source||'IMPORTED');$('stats').textContent=`${(model.positions.length/3).toLocaleString()} POINTS · ${(model.indices.length/3).toLocaleString()} FACES`;fit();if(object.isPoints)object.material.size=span*.004;drawPair();renderRecords();buttons();status(model.synthetic?'กำลังแสดงห้องจำลอง ไม่ใช่ข้อมูล LiDAR จริง':'นำเข้าแล้ว · ตรวจหน่วยและบันทึกโปรเจกต์เพื่อเก็บในเบราว์เซอร์');}
function renderRecords(){$('count').textContent=String(model?.measurements.length||0).padStart(2,'0');$('records').replaceChildren();for(const r of model?.measurements||[]){const row=document.createElement('div');row.className='record';const button=document.createElement('button');const label=document.createElement('span');label.textContent=r.name;const value=document.createElement('strong');value.textContent=distance(r.a,r.b).toFixed(3)+' m';const note=document.createElement('small');note.textContent=new Date(r.date).toLocaleString()+' · แตะเพื่อดูจุด';button.append(label,value,note);button.onclick=()=>{pair=[r.a,r.b];drawPair();};row.append(button);$('records').append(row);}if(!model?.measurements.length){const p=document.createElement('p');p.className='muted';p.textContent='ยังไม่มีผลวัดที่บันทึก';$('records').append(p);}}
$('fit').onclick=fit;$('measure').onclick=()=>{measuring=!measuring;buttons();status(measuring?'โหมดวัด: แตะจุด A และ B บนโมเดล':'โหมดดูโมเดล: ลากเพื่อหมุน ซูมด้วยสองนิ้ว');};$('clear').onclick=()=>{pair=[];drawPair();};
if(renderer){renderer.domElement.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,id:e.pointerId};});renderer.domElement.addEventListener('pointerup',e=>{if(!measuring||!object||!down||down.id!==e.pointerId||Math.hypot(e.clientX-down.x,e.clientY-down.y)>6)return;down=null;const r=renderer.domElement.getBoundingClientRect(),mouse=new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),ray=new THREE.Raycaster();ray.params.Points.threshold=span*.012;ray.setFromCamera(mouse,camera);const hit=ray.intersectObject(object,false)[0];if(!hit){status('ไม่พบพื้นผิวหรือจุด กรุณาแตะบนโมเดล');return;}const p=object.isPoints?new THREE.Vector3().fromBufferAttribute(object.geometry.attributes.position,hit.index):hit.point;if(pair.length===2)pair=[];pair.push(p.toArray());drawPair();});}
function parseFile(file){return new Promise((resolve,reject)=>{const worker=new Worker('./parser-worker.mjs',{type:'module'});const timeout=setTimeout(()=>{worker.terminate();reject(new Error('ไฟล์ใช้เวลาประมวลผลเกิน 30 วินาที'));},30000);const done=()=>{clearTimeout(timeout);worker.terminate();};worker.onmessage=e=>{done();e.data.error?reject(new Error(e.data.error)):resolve(e.data.model);};worker.onerror=()=>{done();reject(new Error('อ่านไฟล์ไม่สำเร็จ'));};file.text().then(text=>worker.postMessage({text,name:file.name,scale:Number($('unit').value)})).catch(e=>{done();reject(e);});});}
$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024){status('ไฟล์เกิน 20 MB กรุณาลดขนาดก่อนนำเข้า',true);e.target.value='';return;}busy=true;buttons();status('กำลังอ่านไฟล์บนเครื่องของคุณ…');try{show(await parseFile(file));}catch(error){status(error.message,true);}finally{busy=false;buttons();e.target.value='';}};
$('demo').onclick=()=>show(demoModel());
$('saveMeasurement').onclick=async()=>{const name=$('label').value.trim();if(!name||pair.length!==2){status('กรุณาใส่ชื่อผลวัดและเลือกสองจุด',true);return;}if(model.measurements.length>=1000){status('จำกัด 1,000 ผลวัดต่อโปรเจกต์',true);return;}model.measurements.push({id:crypto.randomUUID(),name,date:new Date().toISOString(),a:[...pair[0]],b:[...pair[1]]});$('label').value='';renderRecords();buttons();await save();};
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
$('download').onclick=()=>download(JSON.stringify(model),'3117-project.json','application/json');$('csv').onclick=()=>download(csv(model),'3117-measurements.csv','text/csv;charset=utf-8');$('saveProject').onclick=save;
async function database(){if(db)return db;return new Promise((resolve,reject)=>{const request=indexedDB.open('3117-lidar-web',1);request.onupgradeneeded=()=>request.result.createObjectStore('projects',{keyPath:'id'});request.onsuccess=()=>{db=request.result;resolve(db);};request.onerror=()=>reject(request.error);});}
async function transact(mode,action){const databaseValue=await database();return new Promise((resolve,reject)=>{const tx=databaseValue.transaction('projects',mode),req=action(tx.objectStore('projects'));tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Storage aborted'));});}
async function save(){if(!model||busy)return;busy=true;buttons();try{await transact('readwrite',s=>s.put(structuredClone(model)));status('บันทึกในเบราว์เซอร์นี้แล้ว · ดาวน์โหลด JSON สำรองเพื่อย้ายเครื่อง');await listProjects();}catch(error){status('บันทึกบนเครื่องไม่สำเร็จ (พื้นที่เต็มหรือถูกบล็อก) ผลงานยังอยู่ในหน้าจอ กรุณาดาวน์โหลด JSON',true);}finally{busy=false;buttons();}}
async function listProjects(){try{const projects=await transact('readonly',s=>s.getAll());$('projects').replaceChildren();if(!projects.length){const p=document.createElement('p');p.className='muted';p.textContent='ยังไม่มีโปรเจกต์ที่บันทึก';$('projects').append(p);}for(const p of projects){const b=document.createElement('button');b.textContent=p.name;b.onclick=()=>{if(busy)return;try{show(p);}catch(error){status(error.message,true);}};$('projects').append(b);}}catch{status('เบราว์เซอร์ไม่อนุญาตการเก็บข้อมูลถาวร ใช้ดาวน์โหลด JSON สำรองแทน',true);}}
listProjects();
